#include "live602_runtime.h"
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
void values(const std::vector<float>& value){std::cout<<'[';for(size_t i=0;i<value.size();++i){if(i)std::cout<<',';std::cout<<value[i];}std::cout<<']';}
int main(int argc,char** argv){try{if(argc!=2)throw std::runtime_error("usage: probe MODEL");live602::Live602Runtime model(argv[1]);std::cout<<std::setprecision(9);std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;std::istringstream in(line);char kind;std::string word,extra;in>>kind;if(kind=='R'){if(in>>word)throw std::runtime_error("R takes no address");model.Reset();std::cout<<"{\"reset\":true}"<<std::endl;continue;}if((kind!='D'&&kind!='F')||!(in>>word)||(in>>extra))throw std::runtime_error("expected D|F aligned_byte_address");const bool hex=word.size()>2&&word[0]=='0'&&(word[1]=='x'||word[1]=='X');const size_t start=hex?2:0;if(word.empty()||word.find_first_not_of(hex?"0123456789abcdefABCDEF":"0123456789",start)!=std::string::npos)throw std::runtime_error("unsigned decimal or0x address required");size_t end=0;uint64_t address=std::stoull(word,&end,hex?16:10);if(end!=word.size())throw std::runtime_error("invalid address");auto result=model.Infer(address,kind=='D');std::cout<<"{\"address\":"<<address<<",\"demand\":"<<(result.demand?"true":"false")<<",\"emit\":"<<(result.emit?"true":"false")<<",\"count\":"<<result.count<<",\"K\":"<<result.count<<",\"count_raw\":"<<result.count_raw<<",\"truncated\":false,\"macs\":"<<result.macs<<",\"nonlinears\":"<<result.nonlinears<<",\"hidden\":";values(result.hidden);std::cout<<",\"cell\":";values(result.cell);std::cout<<",\"actions\":[";for(size_t i=0;i<result.actions.size();++i){if(i)std::cout<<',';const auto& action=result.actions[i];std::cout<<"{\"address\":"<<action.address<<",\"delta\":"<<action.delta<<",\"fill\":"<<action.fill<<",\"fill_index\":"<<action.fill_index<<",\"coordinate\":"<<action.coordinate<<'}';}std::cout<<"]}"<<std::endl;}}catch(const std::exception& error){std::cerr<<error.what()<<std::endl;return 1;}return 0;}
